BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();m uuid;viewer uuid;one uuid;two uuid;third uuid;folder uuid;click uuid;r jsonb;renamed jsonb;s jsonb;protected jsonb;dynamic jsonb;check_value jsonb;result jsonb;i integer;report_id uuid;share_id uuid;expired jsonb;before_count integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(a),(u),(v);INSERT INTO public.user_roles VALUES(a,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(u,'user','Report owner') RETURNING id INTO m;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label,role) VALUES(v,'user','Viewer','viewer') RETURNING id INTO viewer;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Report folder','edit') RETURNING id INTO folder;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','report-one','https://example.com/SECRET') RETURNING id INTO one;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','report-two','https://example.com/OTHER-SECRET') RETURNING id INTO two;
 INSERT INTO public.redirect_link_metadata(redirect_key,folder_id) VALUES('redirects:'||one,folder),('redirects:'||two,folder);
 click:=public.record_redirect_visit(one,'/go/report-one',NULL,'https://private.example.com/secret','private agent','CH','private hash',302,NULL,'https://example.com/SECRET','{"city":"Private City","device":"Mobile","browser":"Safari","os":"iOS"}');
 PERFORM public.record_redirect_visit(two,'/go/report-two',NULL,NULL,'fixture','US','private hash',302,NULL,'https://example.com/OTHER-SECRET','{}');
 PERFORM public.record_redirect_conversion(jsonb_build_object('kind','lead','clickId',click,'customerExternalId','private-customer','eventId','report-lead','eventName','Private event'));
 r:=public.redirect_saved_report_resource('create',u,m,p_values=>jsonb_build_object('name','Private saved report','filters',jsonb_build_object('linkIds',jsonb_build_array(one))));report_id:=(r->>'id')::uuid;
 BEGIN PERFORM public.redirect_saved_report_resource('get',v,viewer,report_id);RAISE EXCEPTION 'Other user read saved report';EXCEPTION WHEN no_data_found THEN NULL;END;
 renamed:=public.redirect_saved_report_resource('patch',u,m,report_id,jsonb_build_object('name','Renamed','version',r->>'version'));
 IF renamed->>'version'=r->>'version' OR renamed->'filters'<>r->'filters' THEN RAISE EXCEPTION 'Patch lost fields/version';END IF;
 BEGIN PERFORM public.redirect_saved_report_resource('patch',u,m,report_id,jsonb_build_object('name','Stale','version',r->>'version'));RAISE EXCEPTION 'Stale report overwrite';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('patch',u,m,report_id,jsonb_build_object('version',renamed->>'version','filters','{"interval":"invalid"}'::jsonb));RAISE EXCEPTION 'Invalid saved filter persisted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_saved_report_resource('get',u,m,report_id)->>'version'<>renamed->>'version' THEN RAISE EXCEPTION 'Rejected patch changed report version';END IF;
 s:=public.redirect_report_share_resource('create',u,m,report_id,p_values=>jsonb_build_object('title','Published title','reportVersion',renamed->>'version'));share_id:=(s->>'id')::uuid;
 check_value:=public.redirect_public_report_check(share_id,repeat('a',64));
 result:=public.redirect_public_report_read(share_id,(check_value->>'version')::uuid);
 IF (result#>>'{report,totals,clicks}')::int<>1 OR (result#>>'{report,totals,leads}')::int<>0 OR (result->>'linkCount')::int<>1 THEN RAISE EXCEPTION 'Click-only public scope leaked conversions/other links';END IF;
 r:=public.redirect_saved_report_resource('patch',u,m,report_id,jsonb_build_object('version',renamed->>'version','filters',jsonb_build_object('linkIds',jsonb_build_array(one,two))));
 result:=public.redirect_public_report_read(share_id,(check_value->>'version')::uuid);
 IF (result#>>'{report,totals,clicks}')::int<>1 THEN RAISE EXCEPTION 'Saved report edits expanded old share';END IF;
 BEGIN PERFORM public.redirect_report_share_resource('create',u,m,report_id,p_values=>jsonb_build_object('title','Forbidden','reportVersion',r->>'version'));RAISE EXCEPTION 'Member published multi-link dashboard';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.redirect_folder_members VALUES(folder,m,'view');
 BEGIN PERFORM public.redirect_public_report_read(share_id,(check_value->>'version')::uuid);RAISE EXCEPTION 'Publisher lost edit permission but sharing survived';EXCEPTION WHEN no_data_found THEN NULL;END;
 result:=public.redirect_saved_report_resource('run',u,m,report_id);
 IF (result#>>'{totals,clicks}')::int<>2 THEN RAISE EXCEPTION 'View-only private report stopped working';END IF;
 UPDATE public.redirect_folder_members SET permission='edit' WHERE folder_id=folder AND member_id=m;
 PERFORM public.redirect_report_share_resource('revoke',u,m,report_id,share_id);
 BEGIN PERFORM public.redirect_public_report_check(share_id,repeat('a',64));RAISE EXCEPTION 'Revoked URL survived';EXCEPTION WHEN no_data_found THEN NULL;END;
 r:=public.redirect_saved_report_resource('create',a,NULL,p_values=>jsonb_build_object('name','Folder report','filters',jsonb_build_object('folderId',folder)));
 s:=public.redirect_report_share_resource('create',a,NULL,(r->>'id')::uuid,p_values=>jsonb_build_object('title','Fixed links','reportVersion',r->>'version','includeConversions',true));
 dynamic:=public.redirect_report_share_resource('create',a,NULL,(r->>'id')::uuid,p_values=>jsonb_build_object('title','Future folder links','reportVersion',r->>'version','scopeMode','folder'));
 protected:=public.redirect_report_share_resource('create',a,NULL,(r->>'id')::uuid,p_values=>jsonb_build_object('title','Protected','reportVersion',r->>'version'),p_password_hash=>'{"algorithm":"PBKDF2-SHA256","iterations":600000,"salt":"fixture","hash":"fixture"}');
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','report-third','/events') RETURNING id INTO third;
 INSERT INTO public.redirect_link_metadata(redirect_key,folder_id) VALUES('redirects:'||third,folder);
 PERFORM public.record_redirect_visit(third,'/go/report-third',NULL,NULL,'fixture','DE','hash',302,NULL,'/events','{}');
 check_value:=public.redirect_public_report_check((s->>'id')::uuid,repeat('a',64));result:=public.redirect_public_report_read((s->>'id')::uuid,(check_value->>'version')::uuid);
 IF (result#>>'{report,totals,clicks}')::int<>2 OR (result#>>'{report,totals,leads}')::int<>1 THEN RAISE EXCEPTION 'Snapshot scope or conversion opt-in failed';END IF;
 check_value:=public.redirect_public_report_check((dynamic->>'id')::uuid,repeat('b',64));result:=public.redirect_public_report_read((dynamic->>'id')::uuid,(check_value->>'version')::uuid);
 IF (result#>>'{report,totals,clicks}')::int<>3 THEN RAISE EXCEPTION 'Explicit future-folder sharing did not include new link';END IF;
 check_value:=public.redirect_public_report_check((protected->>'id')::uuid,repeat('c',64));
 BEGIN PERFORM public.redirect_public_report_read((protected->>'id')::uuid,(check_value->>'version')::uuid);RAISE EXCEPTION 'Password gate bypass';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 result:=public.redirect_public_report_read((protected->>'id')::uuid,(check_value->>'version')::uuid,true);
 IF result->>'title'<>'Protected' THEN RAISE EXCEPTION 'Verified gate failed';END IF;
 FOR i IN 1..10 LOOP result:=public.redirect_public_report_check((protected->>'id')::uuid,repeat('c',64),true);IF result?'retryAfter' THEN RAISE EXCEPTION 'Premature password throttle';END IF;END LOOP;
 result:=public.redirect_public_report_check((protected->>'id')::uuid,repeat('c',64),true);IF (result->>'retryAfter')::int NOT BETWEEN 1 AND 900 THEN RAISE EXCEPTION 'Password budget absent';END IF;
 UPDATE public.redirect_report_shares SET version=gen_random_uuid() WHERE id=(protected->>'id')::uuid;
 BEGIN PERFORM public.redirect_public_report_read((protected->>'id')::uuid,(check_value->>'version')::uuid,true);RAISE EXCEPTION 'Stale verified password accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 expired:=public.redirect_report_share_resource('create',a,NULL,(r->>'id')::uuid,p_values=>jsonb_build_object('title','Expiring','reportVersion',r->>'version','expiresAt',clock_timestamp()+interval '1 day'));
 UPDATE public.redirect_report_shares SET created_at=now()-interval '2 days',expires_at=now()-interval '1 day' WHERE id=(expired->>'id')::uuid;
 BEGIN PERFORM public.redirect_public_report_check((expired->>'id')::uuid,repeat('d',64));RAISE EXCEPTION 'Expired dashboard survived';EXCEPTION WHEN no_data_found THEN NULL;END;
 SELECT count(*) INTO before_count FROM public.redirect_report_budgets;
 BEGIN PERFORM public.redirect_public_report_check(gen_random_uuid(),repeat('e',64));RAISE EXCEPTION 'Unknown dashboard accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF (SELECT count(*) FROM public.redirect_report_budgets)<>before_count THEN RAISE EXCEPTION 'Unknown URLs polluted budgets';END IF;
 DELETE FROM public.user_roles WHERE user_id=a;
 BEGIN PERFORM public.redirect_public_report_check((dynamic->>'id')::uuid,repeat('a',64));RAISE EXCEPTION 'Removed workspace owner still published folder';EXCEPTION WHEN no_data_found THEN NULL;END;
 INSERT INTO public.user_roles VALUES(a,'admin');
 PERFORM public.redirect_saved_report_resource('delete',a,NULL,(r->>'id')::uuid);
 BEGIN PERFORM public.redirect_public_report_check((dynamic->>'id')::uuid,repeat('a',64));RAISE EXCEPTION 'Deleted report share survived';EXCEPTION WHEN no_data_found THEN NULL;END;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF has_function_privilege(current_user,'public.redirect_public_report_check(uuid,text,boolean)','execute') OR has_function_privilege(current_user,'public.redirect_public_report_read(uuid,uuid,boolean)','execute') THEN RAISE EXCEPTION 'Public Data API exposed private password/aggregate RPC';END IF;
 BEGIN PERFORM * FROM public.redirect_report_shares;RAISE EXCEPTION 'Share table exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
